"""Final source/manifest QA and seal. No raw reads, SDK/tests or source edits."""
from pathlib import Path
import datetime,hashlib,json
P=Path(__file__).resolve().parents[1];WT=P.parents[2]
def sha(b):return hashlib.sha256(b).hexdigest()
def load(p):return json.loads(p.read_text(encoding='utf-8'))
def new(p,obj):assert not p.exists();p.write_text(json.dumps(obj,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf-8')
def main():
    assert not (P/'SEAL.json').exists()
    m=load(P/'manifest.json');reg=load(P/'CASE_AND_ATTEMPT_REGISTRY.json');entries={e['source_relative']:e for e in m['entries']};s=m['summary']
    required=['ARCHIVE_PHASE1_RECEIPT.json','ARCHIVE_PHASE1_OPERATION_FAILURE_001.txt','reports/R15_SOFTWARE_FAILURE_ERRATUM.md','batches/r16_jump_roll_train33/BATCH_RESULT.json','FSM_DETECTOR_V1/INDEX.json','CONTACT_PROXY_NOMINAL_V1/INDEX.json','SPR_AUDIT/ARM_OBJECT_BUILD_V1/INDEX.json']
    for rel in required:assert rel in entries and entries[rel]['archive_path'],rel+' missing'
    counts={};checked=0
    for rel,e in entries.items():
        group=rel.split('/')[0];counts[group]=counts.get(group,0)+1
        if e['archive_path']:
            assert sha((WT/e['archive_path']).read_bytes())==e['archive_sha256'],rel
            if not e['redactions']:assert e['original_sha256']==e['archive_sha256']
            checked+=1
    arm=[e for rel,e in entries.items() if rel.startswith('SPR_AUDIT/ARM_OBJECT_BUILD_V1/') and rel.endswith('.o')]
    assert len(arm)==6 and all(e['original_sha256'] is not None and e['capture_kind'].startswith('index_only') for e in arm)
    assert len(reg['physical_cases'])==446 and len([x for x in reg['software_cases'] if x['case_id'].startswith('r15_')])==33
    partial_controls=sum(x['stored_payload_not_rewritten'].get('controls',0) for x in reg['software_cases'] if x['case_id'].startswith('r15_'))
    partial_steps=sum(x['stored_payload_not_rewritten'].get('physics_steps',0) for x in reg['software_cases'] if x['case_id'].startswith('r15_'))
    q={'status':'PH2_TEXT_HASH_REFERENCE_SCOPE_QA_PASS_NOT_ROBOT_QUALIFICATION','summary':s,'text_SHA_pairs_verified':checked,'admitted_root_counts':counts,'ARM6objects_indexed_existing_producerSHA_only':[{'path':e['path'],'bytes':e['bytes'],'producer_SHA':e['original_sha256']} for e in arm],'R15software33_partial_consumed_controls':partial_controls,'R15software33_partial_consumed_physics_steps':partial_steps,'R15_valid_completed_jump_evaluations':0,'R15_is_not_robot_zero_of10':True,'R16_result_files':33,'reader_parse_events':m['reader_errors'],'new_physics_for_archive':0,'new_test_runs':0,'new_raw_content_hashes':0}
    new(P/'FINAL_CAPTURE_QA.json',q)
    note='''# Archive MOD4v1 robust traditional PHASE2 through R16\n\nDiagnostic evidence archival only. Full scope is PH2_ROOT_SCOPE.md/json; all original source/config/result/error/report bytes or prior identical Phase1Git references are mapped in manifest.json. Actual accepted source scope ends at R16; shared mutable files after the R16closed batch time stay pending unless a parent-declared sealed module/H1/H2/R16artifact.\n\n446physical result files through R16 are retained, not all passes. The33R15API child failures are a SEPARATE software category, not a robot0/10jump ability score; consumed prefix controls/physics are preserved and old unsaved row traces remain absent. R16corrected IDs33rc0include nominal cases and30DR: original roll6/10clear,5/10end2s; roll_long.11s9/10clear,7/10end2s,0/10zero-nonwheel-end2s; pitchD1/10. No wrong old result is replaced. Static guide identities are candidates, not retroactive original force identity or all-surface flight proof.\n\nH1P25stand60/64andforward63/64, H2positive4pi64/64, MPC8nominal/train successes, Ctoy/math passes, FSM63synthetic methods, CONTACT32synthetic+13static forwards, or ARM6/6compile objects are not wholeGoal/270mm/RM/realboard graduation. C QPv1/v2 real-H numerical limitations and failed attempts remain alongside toy passes. ARM is -c only, no native ARM run/BSP/firmware. Proposed thresholds remain proposed. Overall Goal remains ACTIVE.\n\nACTIVE portable_control_v3_current, ALL R17/R18/R19/R20/R21/R22+files (including software prep assertions), exact RM_GRID_SCUT terrain and other future/source changes remain PH3_PENDING. Do not chase later round progress or rerun physics/tests/once for archival. Next movingCOMprototype starts only after this seal and is future PH3 work, not an admission here.\n\nLarge trace/binary/NPZ/USD/STL/ZIP/objects stay at actual source. RawSHA entries are only existing producer claims with path/size/provenance, unknown/conflicting hashes remain unknown, no archival raw reread. Small ARM objects are also indexed only. All earlier PH1postcommit receipts/operation reports found in source are admitted; this PH2postcommit receipt/verification will be explicitly PH3pending, not a recursive new experiment.\n\nUse unchanged archive_tools/record_experiment.py once for unique diagnostic id mod4v1-robust-traditional-phase2, date actual at recording. Narrow single-add adapter uses only NEW phase2 directory+generated record, validates exact expected staged paths, allA/noD/foreign paths and every staged blob SHA/map. Push only explicit OWNbranch+newtag with --atomic, no force/main/expert destination. Preserve Phase1commit/tag/object. Compare fresh immediate pre/post owned-push remote main, record any earlier concurrent changes separately; never restore another session's HEAD/index or roll back main. Commit success/push failure means push existing objects only, never replay record/tag.\n\nNo training/canonical budget/parent source modification, no new agent, hardware or SSH. New physics steps0, test reruns0, raw content hashes0 for this archive.\n'''
    (P/'NOTE.md').write_text(note,encoding='utf-8')
    readme=f'''# MOD4v1 robust traditional PHASE2 — evidence through R16\n\n**Stage archive only; overall Goal remains ACTIVE. R17+ and active C-v3 are PH3pending.**\n\n- [Scope](<PH2_ROOT_SCOPE.md>) / [exact machine scope](<PH2_ROOT_SCOPE.json>).\n- [Manifest](<manifest.json>):{s['selected_entries']}admitted originals; {s['new_text_copies']}new text copies/{s['new_text_bytes']:,}bytes plus{s['existing_phase1_Git_text_references']}unchanged Phase1Git references. Every text source↔archive SHA pair verified; redactions{s['redactions']}.\n- [Case/attempt registry](<CASE_AND_ATTEMPT_REGISTRY.json>):446physical result files (includes30old Phase1cases),33R15software failures separately, batch summaries not double-counted, saved unit/build/reader/error attempts retained.\n- R15consumed prefix work retained:{partial_controls}controls/{partial_steps}physics steps across errors. Valid completed jump evaluations0, **not robot0/10**. Missing old prefix row traces are not reconstructed.\n- R16corrected33cases retained with failures: roll6/10clear/5/10end2s; long.11s9/10clear/7/10end2s and0/10zero-nonwheel-end2s; pitchD1/10. No full jump graduation.\n- Raw originals indexed only:{s['raw_index_only']}, known existing bound producerSHAs{s['raw_existing_producer_SHA_known']}, unknown{s['raw_index_only']-s['raw_existing_producer_SHA_known']}; external metadata entries{s['external_original_metadata_entries']}. Six ARM objects have existing producerSHA, not rehashed.\n- [Capture QA](<FINAL_CAPTURE_QA.json>), [capture counters](<CAPTURE_SUMMARY.json>), [future/pending paths](<PH3_PENDING.json>), [record note](<NOTE.md>).\n\nH1/H2 protocols and derivative reports, MPC8, C QPv1/v2 actual-H insufficiency, ODOM, FSM, CONTACT and compile-only ARM6/6 are preserved. These do not qualify fullGoal/270mm/RM/board. Sensor/force/COMprototypes remain model proposals, not contact identity or measured force calibration.\n\nNo physics or unit rerun for archival, no raw reread to manufactureSHA, no SSH/realIO/newagent/GPU/budget change. Only own isolated branch and this new phase directory are write/stage targets; Phase1source/tag is not replayed. The next PH2commit receipt will be postcommit PH3pending to avoid receipt recursion.\n'''
    (P/'README.md').write_text(readme,encoding='utf-8')
    new(P/'SEAL.json',{'sealed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'through_R16_plus_explicit_sealed_modules_only','manifest_sha256':sha((P/'manifest.json').read_bytes()),'root_scope_sha256':sha((P/'PH2_ROOT_SCOPE.json').read_bytes()),'registry_sha256':sha((P/'CASE_AND_ATTEMPT_REGISTRY.json').read_bytes()),'pending_sha256':sha((P/'PH3_PENDING.json').read_bytes()),'final_QA_sha256':sha((P/'FINAL_CAPTURE_QA.json').read_bytes()),'summary':s,'source_admissions_closed':True,'postcommit_receipt':'PH3pending; no record/tag recursion','goal':'active'})
    print(json.dumps({'sealed':True,'manifest_sha256':sha((P/'manifest.json').read_bytes()),'source_summary':s,'ARM_objects':len(arm),'R15_partial_consumed_physics_steps':partial_steps},indent=2))
if __name__=='__main__':main()
